values ('ap_precalculus', 3, '3.9', array['3.9', '3.10']::text[], 'list_sequence', 'Restricted domains that define inverse trig functions', 'Domain restrictions that make sine, cosine, and tangent invertible.', '[{"label": "Sine", "meaning": "\\left[-\\frac{\\pi}{2},\\frac{\\pi}{2}\\right]"}, {"label": "Cosine", "meaning": "[0,\\pi]"}, {"label": "Tangent", "meaning": "\\left(-\\frac{\\pi}{2},\\frac{\\pi}{2}\\right)"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-027; ced=3.9.A.3 "domain of the sine function is restricted to [−π/2, π/2], the cosine function to [0, π], and the tangent function to (−π/2, π/2)"')
