values ('ap_precalculus', 3, '3.11', array['3.11']::text[], 'list_sequence', 'Graph features of secant, cosecant, and cotangent', 'Key graph characteristics of the reciprocal trigonometric functions.', '[{"label": "Secant", "meaning": "vertical asymptotes where cosine is zero; range (-\\infty,-1]\\cup[1,\\infty)"}, {"label": "Cosecant", "meaning": "vertical asymptotes where sine is zero; range (-\\infty,-1]\\cup[1,\\infty)"}, {"label": "Cotangent", "meaning": "vertical asymptotes where tan θ = 0; decreasing between consecutive asymptotes"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-031; ced=3.11.A.3 "range of (−∞, −1] ∪ [1, ∞)"; 3.11.A.5')
