values ('ap_precalculus', 3, '3.12', array['3.12']::text[], 'formula', 'Forms derived from the Pythagorean identity', '\tan^2\theta=\sec^2\theta-1,\qquad \arcsin x=\arccos\left(\sqrt{1-x^2}\right)', '[]'::jsonb, NULL, 'The arcsin–arccos relationship holds only with appropriate domain restrictions.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-033; ced=3.12.A.2 "tan²θ = sec²θ − 1 ... arcsin x = arccos(√(1 − x²)), with appropriate domain restrictions"')
