values ('ap_precalculus', 3, '3.13', array['3.13']::text[], 'formula', 'Complex number in rectangular and polar form', 'a+bi\ \text{for rectangular }(a,b);\qquad (r\cos\theta)+i\,(r\sin\theta)\ \text{for polar }(r,\theta)', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-039; ced=3.13.A.4 "expressed as (r cos θ) + i(r sin θ)"')
