values ('ap_precalculus', 3, '3.13', array['3.13', '3.14']::text[], 'vocabulary', 'Polar coordinates (r, θ)', 'Polar coordinates (r, θ) locate a point using the angle θ of a terminal ray in standard position and the signed radial displacement r from the origin.', '[]'::jsonb, NULL, 'A negative r means displacement along the line of the terminal ray in the opposite direction. The same point has many polar representations.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-036; ced=3.13.A.1 "Polar coordinates of a point are defined as an ordered pair, (r, θ)"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 3, '3.13', array['3.13']::text[], 'formula', 'Polar to rectangular conversion', 'x=r\cos\theta,\qquad y=r\sin\theta', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-037; ced=3.13.A.2 "x = r cos θ and y = r sin θ"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 3, '3.13', array['3.13']::text[], 'formula', 'Rectangular to polar conversion', 'r=\sqrt{x^2+y^2},\qquad \theta=\begin{cases}\arctan\left(\dfrac{y}{x}\right), & x>0\\[2mm] \arctan\left(\dfrac{y}{x}\right)+\pi, & x<0\end{cases}', '[]'::jsonb, NULL, 'The CED gives no case for x = 0. For x < 0 you must add π to the arctangent.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-038; ced=3.13.A.3 "θ = arctan(y/x) for x > 0 or θ = arctan(y/x) + π for x < 0"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 3, '3.14', array['3.14', '3.15']::text[], 'convention', 'Meaning of a polar function graph r = f(θ)', 'The graph of r = f(θ) consists of input-output pairs in which the input is an angle measure from the polar axis and the output is a signed radius, and its domain can be restricted by choosing endpoints for the desired angle and radius.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-040; ced=3.14.A.1 "input values are angle measures and the output values are radii"; 3.14.A.3')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 3, '3.15', array['3.15']::text[], 'formula', 'Average rate of change of a polar function', '\frac{f(\theta_2)-f(\theta_1)}{\theta_2-\theta_1}', '[]'::jsonb, NULL, 'This is the change in signed radius per radian over the interval, and it can be used to estimate function values within the interval.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-043; ced=3.15.A.4 "ratio of the change in the signed radius values to the change in θ"; 3.15.A.5')
