values ('ap_precalculus', 3, '3.15', array['3.15']::text[], 'convention', 'Relative extrema of a polar function', 'If a polar function changes from increasing to decreasing or from decreasing to increasing on an interval, it has a relative extremum there, corresponding to a point relatively closest to or farthest from the origin.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u3-r1-042; ced=3.15.A.3 "relative extremum ... closest to or farthest from the origin"')
